import type { AppService } from '@/types/system';
import { getFilename } from '@/utils/path';

/**
 * Import-only formats that are converted to EPUB before ingestion. They pass
 * every import whitelist but never reach the reader as-is — `importBooksRun`
 * routes them through {@link convertDocxToEpubFile} first.
 */
export const CONVERTIBLE_IMPORT_EXTS = ['docx'];

export const isConvertibleImportFile = (filename: string): boolean => {
  const dot = filename.lastIndexOf('.');
  if (dot < 0) return false;
  return CONVERTIBLE_IMPORT_EXTS.includes(filename.slice(dot + 1).toLowerCase());
};

/**
 * Convert a `.docx` (picked `File` or on-disk path) into an importable EPUB
 * `File`, reusing the same conversion engine as Send-to-Readest (mammoth →
 * sanitized HTML → EPUB with a heading TOC). Everything else must be filtered
 * out by the caller via {@link isConvertibleImportFile}.
 */
export const convertDocxToEpubFile = async (
  file: File | string,
  appService: AppService,
): Promise<File> => {
  const fileName = typeof file === 'string' ? getFilename(file) : file.name;
  const data =
    typeof file === 'string'
      ? await appService.readFile(file, 'None', 'binary')
      : await file.arrayBuffer();
  if (typeof data === 'string' || !data || data.byteLength === 0) {
    throw new Error(`Could not read .docx file: ${fileName}`);
  }
  const { convertToEpub } = await import('@/services/send/conversion/convertToEpub');
  const converted = await convertToEpub({ kind: 'docx', bytes: data, fileName });
  return converted.file;
};
