import clsx from 'clsx';
import { useEffect, useRef, useState } from 'react';
import { MdCheckCircle, MdCheckCircleOutline, MdChevronRight, MdChevronLeft } from 'react-icons/md';
import { useEnv } from '@/context/EnvContext';
import { useTranslation } from '@/hooks/useTranslation';
import { BooksGroup } from '@/types/book';
import { LibraryViewModeType, LibraryCoverFitType } from '@/types/settings';
import BookCover from '@/components/BookCover';
import { useSettingsStore } from '@/store/settingsStore';
import { useLibraryStore } from '@/store/libraryStore';
import { setBookGroup } from '@/utils/book';

interface GroupItemProps {
  mode: LibraryViewModeType;
  group: BooksGroup;
  coverFit?: LibraryCoverFitType;
  skeuomorphicCovers?: boolean;
  isSelectMode: boolean;
  groupSelected: boolean;
  /** 轻点分组：进入分组（多选态下为选中该分组） */
  onOpenGroup?: () => void;
  /** 多选态下长按分组：选中该分组 */
  onLongPressGroup?: () => void;
}

/** 卡片设计基准宽度（Mini Archive 原稿 .folder-card 220×310），按格子宽度等比缩放 */
const CARD_BASE_W = 220;
/** 文件夹命名色板（原稿 merge-palette 的 swatch 顺序） */
const GROUP_COLORS = ['white', 'blue', 'red', 'yellow', 'pink', 'green', 'black'] as const;
type GroupColorName = (typeof GROUP_COLORS)[number];
/** 调色盘圆点的展示色（与原稿 swatch 背景一致） */
const SWATCH_HEX: Record<GroupColorName, string> = {
  white: '#ffffff',
  blue: '#2f8cff',
  red: '#ff5a5f',
  yellow: '#ffd34d',
  pink: '#ff4090',
  green: '#34c759',
  black: '#222222',
};
/** 默认封面色：蜂蜜黄，与旧版默认强调色 #d97706 的暖调一致 */
const DEFAULT_GROUP_COLOR: GroupColorName = 'yellow';
/** 旧版（Podcast Folder 设计）按分组存的是十六进制强调色，读取时映射到命名色 */
const LEGACY_HEX_TO_COLOR: Record<string, GroupColorName> = {
  '#ffffff': 'white',
  '#ff3b30': 'red',
  '#ff9500': 'yellow',
  '#d97706': 'yellow',
  '#34c759': 'green',
  '#007aff': 'blue',
  '#af52de': 'pink',
};

const GROUP_COLOR_KEY = 'readest.groupAccentColors';
const loadGroupColors = (): Record<string, string> => {
  try {
    return JSON.parse(localStorage.getItem(GROUP_COLOR_KEY) ?? '{}');
  } catch {
    return {};
  }
};
const loadGroupColor = (id: string): GroupColorName => {
  try {
    const raw = JSON.parse(localStorage.getItem(GROUP_COLOR_KEY) ?? '{}')?.[id];
    if (typeof raw === 'string') {
      const lower = raw.toLowerCase();
      if ((GROUP_COLORS as readonly string[]).includes(lower)) return lower as GroupColorName;
      if (LEGACY_HEX_TO_COLOR[lower]) return LEGACY_HEX_TO_COLOR[lower];
    }
  } catch {
    /* ignore malformed cache */
  }
  return DEFAULT_GROUP_COLOR;
};
const saveGroupColor = (id: string, color: GroupColorName) => {
  const map = loadGroupColors();
  map[id] = color;
  try {
    localStorage.setItem(GROUP_COLOR_KEY, JSON.stringify(map));
  } catch {
    /* ignore quota errors */
  }
};

/** 内页书卡的展开变量：照搬原稿的种子随机公式，同一本书的展开姿态稳定 */
const innerCardVars = (idx: number): React.CSSProperties => {
  const seed = 9 + idx * 17;
  const rand = (min: number, max: number) => {
    const x = Math.sin(seed + idx * 1.3) * 10000;
    const v = x - Math.floor(x);
    return min + v * (max - min);
  };
  return {
    '--dx': `${rand(8, 30).toFixed(1)}px`,
    '--dy': `${rand(-12, 5).toFixed(1)}px`,
    '--dz': `${idx * 14}px`,
    '--ds': rand(0.86, 0.97).toFixed(3),
    '--dr': `${rand(-2.4, 2.4).toFixed(2)}deg`,
    /* 收起态错位：每张纸微退、微旋，露出纸叠边缘增强层级感 */
    '--sx': `${-idx * 2.2}px`,
    '--sy': `${-idx * 1.4}px`,
    '--sr': `${(idx * 0.8 - 0.4).toFixed(2)}deg`,
  } as React.CSSProperties;
};

type EditState = 'none' | 'editing' | 'picking' | 'renaming';

const GroupItem: React.FC<GroupItemProps> = ({
  mode,
  group,
  coverFit,
  skeuomorphicCovers,
  isSelectMode,
  groupSelected,
  onOpenGroup,
  onLongPressGroup,
}) => {
  const _ = useTranslation();
  const { appService } = useEnv();
  // Status groups carry an i18n key in `displayName`; series/author/tag/subject
  // groups carry user-authored text that must never be translated.
  const groupLabel = group.localized ? _(group.displayName) : group.displayName;
  const { settings } = useSettingsStore();
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const [showLeftArrow, setShowLeftArrow] = useState(false);
  const [showRightArrow, setShowRightArrow] = useState(false);

  const checkScrollArrows = () => {
    if (mode === 'list' && scrollContainerRef.current) {
      const container = scrollContainerRef.current;
      const hasOverflow = container.scrollWidth > container.clientWidth;

      if (hasOverflow) {
        const isAtStart = container.scrollLeft <= 5;
        const isAtEnd = container.scrollLeft >= container.scrollWidth - container.clientWidth - 5;
        setShowLeftArrow(!isAtStart);
        setShowRightArrow(!isAtEnd);
      } else {
        setShowLeftArrow(false);
        setShowRightArrow(false);
      }
    } else {
      setShowLeftArrow(false);
      setShowRightArrow(false);
    }
  };

  useEffect(() => {
    checkScrollArrows();
    if (mode === 'list' && scrollContainerRef.current) {
      const container = scrollContainerRef.current;
      setTimeout(() => {
        container.style.transform = 'translateZ(0)';
        container.scrollLeft = 0;
      }, 0);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mode, group.books.length, scrollContainerRef.current]);

  const handleScroll = () => {
    checkScrollArrows();
  };

  const scrollLeft = () => {
    if (scrollContainerRef.current) {
      const container = scrollContainerRef.current;
      const scrollAmount = container.clientWidth * 0.5;
      const currentScroll = container.scrollLeft;
      const targetScroll = Math.max(0, currentScroll - scrollAmount);
      container.scrollTo({ left: targetScroll, behavior: 'smooth' });
    }
  };

  const scrollRight = () => {
    if (scrollContainerRef.current) {
      const container = scrollContainerRef.current;
      const scrollAmount = container.clientWidth * 0.5;
      const currentScroll = container.scrollLeft;
      const targetScroll = Math.min(maxScroll(), currentScroll + scrollAmount);
      container.scrollTo({ left: targetScroll, behavior: 'smooth' });
    }
  };

  const maxScroll = () => {
    const container = scrollContainerRef.current;
    return container ? container.scrollWidth - container.clientWidth : 0;
  };

  const stopEvent = (e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    e.stopPropagation();
  };

  const handleLeftArrowClick = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    scrollLeft();
  };

  const handleRightArrowClick = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    scrollRight();
  };

  /* ------------------------------------------------------------------
   * 网格视图：分组渲染为「Mini Archive」玻璃文件夹卡片（用户 2026-10-28
   * 提供的 code_20261027.html 原样照搬）：七色玻璃后壳 + 内页书卡 +
   * 可开合的玻璃封面（右上角书目计数、左下角分组名）+ 长按出现改色/
   * 改名圆钮 + 原地悬浮调色盘（不弹遮罩）。
   * 交互：轻点封面开合文件夹；轻点展开的内页书卡进入分组；长按进编辑；
   * 多选态下轻点/长按维持原有选中行为。
   * 交互自管：外层 BookshelfItem 的 useLongPress 走 pointerup/onClick，
   * 这里拦下冒泡自己实现轻点与长按，行为不回归。
   * ------------------------------------------------------------------ */
  const cellRef = useRef<HTMLDivElement>(null);
  const [cardZoom, setCardZoom] = useState(0.5);
  const [editState, setEditState] = useState<EditState>('none');
  const [holding, setHolding] = useState(false);
  /** 文件夹封面命名色（white/blue/red/yellow/pink/green/black） */
  const [color, setColor] = useState<GroupColorName>(() => loadGroupColor(group.id));
  /** 文件夹开合：轻点封面展开内页书卡，再点收起（Mini Archive 原稿交互） */
  const [open, setOpen] = useState(false);
  const [nameDraft, setNameDraft] = useState(group.name);
  const lpTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const lpFired = useRef(false);
  const pressStart = useRef<{ x: number; y: number } | null>(null);
  // 书卡标题区（书名 + 进度行）的高度：分组卡片要整体抬高这么多，
  // 底边才和书封底边落在同一条基线上
  const [bookCaptionH, setBookCaptionH] = useState(0);

  // 量一次同网格里书卡的标题区高度（书名行 + 进度行，固定行高所以取值稳定）
  useEffect(() => {
    if (mode !== 'grid') return;
    const cell = cellRef.current;
    if (!cell) return;
    const grid = cell.closest('.rd-shelf-grid') as HTMLElement | null;
    const measure = () => {
      const sample = grid?.querySelector<HTMLElement>('.rd-book-caption');
      setBookCaptionH(sample ? sample.getBoundingClientRect().height : 0);
    };
    measure();
    const sample = grid?.querySelector<HTMLElement>('.rd-book-caption');
    if (!sample) return;
    const ro = new ResizeObserver(measure);
    ro.observe(sample);
    return () => ro.disconnect();
  }, [mode, group.books.length]);

  // 分组 id 变化（改名后 id 随路径变化）时同步封面色与草稿名
  useEffect(() => {
    setColor(loadGroupColor(group.id));
    setOpen(false);
  }, [group.id]);

  // 卡片按所在格子宽度等比缩放（zoom 真实缩小布局占位，不会撑破网格）
  useEffect(() => {
    const el = cellRef.current;
    if (!el || mode !== 'grid') return;
    const measure = () => {
      const w = el.clientWidth;
      if (w > 0) setCardZoom(Math.min(1.8, Math.max(0.4, w / CARD_BASE_W)));
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, [mode]);

  const applyColor = (next: GroupColorName) => {
    setColor(next);
    saveGroupColor(group.id, next);
    setEditState('none');
  };

  const commitRename = () => {
    const newName = nameDraft.trim();
    setEditState('none');
    if (!newName || newName === group.name || group.localized) {
      setNameDraft(group.name);
      return;
    }
    // 复用 GroupingModal 的改名流程：全库扫旧路径（含嵌套子组）逐本迁移
    const { library, setLibrary, getGroupId, refreshGroups } = useLibraryStore.getState();
    library.forEach((book) => {
      if (book.groupName === group.name) {
        setBookGroup(book, getGroupId(newName), newName);
      } else if (book.groupName?.startsWith(`${group.name}/`)) {
        const nestedName = book.groupName.replace(group.name, newName);
        setBookGroup(book, getGroupId(nestedName), nestedName);
      }
    });
    setLibrary([...library]);
    void appService?.saveLibraryBooks(library);
    refreshGroups();
    // 强调色跟分组 id 存 localStorage，改名后迁移到新 id
    const newId = getGroupId(newName);
    if (newId && newId !== group.id) {
      const color = loadGroupColor(group.id);
      if (color) saveGroupColor(newId, color);
    }
  };

  const onCardPointerDown = (e: React.PointerEvent) => {
    e.stopPropagation();
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    const target = e.target as HTMLElement;
    if (target.closest('.gp-action') || target.closest('.gp-palette') || target.closest('.gp-input'))
      return;
    pressStart.current = { x: e.clientX, y: e.clientY };
    lpFired.current = false;
    setHolding(true);
    lpTimer.current = setTimeout(() => {
      lpFired.current = true;
      setHolding(false);
      if (isSelectMode) {
        onLongPressGroup?.();
        return;
      }
      setNameDraft(group.name);
      setEditState('editing');
    }, 500);
  };

  const onCardPointerMove = (e: React.PointerEvent) => {
    if (!pressStart.current) return;
    const dx = Math.abs(e.clientX - pressStart.current.x);
    const dy = Math.abs(e.clientY - pressStart.current.y);
    if (dx > 10 || dy > 10) {
      clearTimeout(lpTimer.current);
      pressStart.current = null;
      setHolding(false);
    }
  };

  const onCardPointerUp = (e: React.PointerEvent) => {
    e.stopPropagation();
    clearTimeout(lpTimer.current);
    setHolding(false);
    if (lpFired.current || !pressStart.current) return;
    const dx = Math.abs(e.clientX - pressStart.current.x);
    const dy = Math.abs(e.clientY - pressStart.current.y);
    pressStart.current = null;
    if (dx > 10 || dy > 10) return;
    // 轻点
    if (isSelectMode) {
      onOpenGroup?.();
      return;
    }
    if (editState !== 'none') {
      // 设计稿行为：编辑态下轻点空白处收起按钮/调色盘
      setEditState('none');
      return;
    }
    // Mini Archive 交互：轻点封面开合文件夹；进入分组由展开后的内页书卡承接
    setOpen((o) => !o);
  };

  const onCardPointerCancel = () => {
    clearTimeout(lpTimer.current);
    pressStart.current = null;
    setHolding(false);
  };

  const onCardClick = (e: React.MouseEvent) => {
    // 指针轻点已由 pointerup 处理；拦住冒泡，防止外层 useLongPress
    // 的 onClick（aria 激活路径）把分组重复打开一次
    e.stopPropagation();
  };

  const stopAll = (e: React.SyntheticEvent) => {
    e.stopPropagation();
    e.preventDefault();
  };

  const gradId = 'gp-rainbow';

  return (
    <div
      className={clsx('group-item', appService?.hasContextMenu ? 'cursor-pointer' : '')}
      // 抬高一个书卡标题区的高度，底边与书封底边对齐
      style={mode === 'grid' ? { marginBottom: bookCaptionH } : undefined}
    >
      <div
        className={clsx(
          'groupitem-main relative flex rounded-sm',
          // 网格态刻意不给底色/阴影：28:41 的格子底板会变成一张
          // "A4 纸"一样的大色块，视觉上比卡片本体还抢眼。
          // 卡片是竖版(220:310)，放进 28:41 的竖条格子里底端对齐
          // (items-end)，与书封/导入瓷砖的底边线一致；mb-auto 抵消外层
          // justify-end，让 28:41 的占位盒从格子顶部开始排——这样盒底
          // (即卡片底边) 恰好落在书封底边所在的高度上。
          mode === 'grid' && 'aspect-[28/41] items-end justify-center',
          mode === 'list' && 'items-center justify-start gap-4 overflow-hidden py-2',
        )}
      >
        {mode === 'grid' ? (
          <div className='gi-folder-cell' ref={cellRef}>
            {/* 原稿的彩虹渐变（改色按钮图标用），全文档共用一个 id */}
            <svg width='0' height='0' style={{ position: 'absolute' }} aria-hidden='true'>
              <defs>
                <linearGradient id={gradId} x1='0%' y1='0%' x2='100%' y2='100%'>
                  <stop offset='0%' stopColor='#ff3b30' />
                  <stop offset='25%' stopColor='#ff9500' />
                  <stop offset='50%' stopColor='#4cd964' />
                  <stop offset='75%' stopColor='#5ac8fa' />
                  <stop offset='100%' stopColor='#5856d6' />
                </linearGradient>
              </defs>
            </svg>
            <div
              className={clsx(
                'gp-card',
                open && 'is-open',
                editState === 'editing' && 'is-editing',
                editState === 'picking' && 'is-picking-color',
                editState === 'renaming' && 'is-renaming',
                holding && 'is-holding',
              )}
              data-color={color}
              style={{ zoom: cardZoom } as React.CSSProperties}
              role='button'
              aria-label={groupLabel}
              aria-expanded={open}
              onPointerDown={onCardPointerDown}
              onPointerMove={onCardPointerMove}
              onPointerUp={onCardPointerUp}
              onPointerCancel={onCardPointerCancel}
              onContextMenu={(e) => e.preventDefault()}
              onClick={onCardClick}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  e.preventDefault();
                  setOpen((o) => !o);
                }
              }}
            >
              <div className='gp-container'>
                <div className='gp-back' />
                <div className='gp-inner-group'>
                  {group.books.slice(0, 4).map((book, idx) => (
                    <div
                      key={book.hash}
                      className='gp-inner-card'
                      style={innerCardVars(idx)}
                      onPointerDown={stopAll}
                      onPointerUp={stopAll}
                      onPointerMove={stopAll}
                      onClick={(e) => {
                        e.stopPropagation();
                        if (!isSelectMode) onOpenGroup?.();
                      }}
                    >
                      <div className='gp-inner-frame'>
                        <BookCover book={book} coverFit='crop' isPreview showSpine={false} />
                      </div>
                    </div>
                  ))}
                </div>
                <div className='gp-front'>
                  <div className='gp-count'>
                    {String(group.books.length).padStart(2, '0')}
                  </div>
                  <div className='gp-face'>
                    {editState === 'renaming' ? (
                      <input
                        type='text'
                        className='gp-input'
                        value={nameDraft}
                        autoFocus
                        autoComplete='off'
                        spellCheck={false}
                        onPointerDown={stopAll}
                        onPointerUp={stopAll}
                        onPointerMove={stopAll}
                        onClick={(e) => e.stopPropagation()}
                        onChange={(e) => setNameDraft(e.target.value)}
                        onBlur={commitRename}
                        onKeyDown={(e) => {
                          if (e.key === 'Enter') {
                            (e.target as HTMLInputElement).blur();
                          } else if (e.key === 'Escape') {
                            setNameDraft(group.name);
                            setEditState('none');
                          }
                        }}
                      />
                    ) : (
                      <h2 className='gp-title'>{groupLabel}</h2>
                    )}
                    <p className='gp-sub'>
                      {_('{{count}} book(s)', { count: group.books.length })}
                    </p>
                    <div className='gp-line' />
                  </div>
                </div>

                {!group.localized && (
                  <button
                    type='button'
                    className='gp-action gp-action-rename'
                    aria-label={_('Rename Group')}
                    title={_('Rename Group')}
                    onPointerDown={stopAll}
                    onPointerUp={stopAll}
                    onPointerMove={stopAll}
                    onClick={(e) => {
                      e.stopPropagation();
                      setNameDraft(group.name);
                      setEditState('renaming');
                    }}
                  >
                    <svg viewBox='0 0 24 24' aria-hidden='true'>
                      <path d='M4.5 13.5L15 3c1.1-1.1 2.9-1.1 4 0l2 2c1.1 1.1 1.1 2.9 0 4L10.5 19.5H21v2H6.5v-5.5L4.5 13.5zM12 17.5L18 11.5L14.5 8L8.5 14V17.5H12z' />
                    </svg>
                  </button>
                )}

                <button
                  type='button'
                  className='gp-action gp-action-color'
                  aria-label={_('Change Color')}
                  title={_('Change Color')}
                  onPointerDown={stopAll}
                  onPointerUp={stopAll}
                  onPointerMove={stopAll}
                  onClick={(e) => {
                    e.stopPropagation();
                    setEditState((s) => (s === 'picking' ? 'editing' : 'picking'));
                  }}
                >
                  <svg viewBox='0 0 24 24' aria-hidden='true'>
                    <path d='M12 22C6.49 22 2 17.51 2 12S6.49 2 12 2s10 4.49 10 10c0 2.4-1.45 4.5-3.5 5.35-.8.33-1.5.95-1.5 1.8v.35c0 1.38-1.12 2.5-2.5 2.5H12zm0-18C7.59 4 4 7.59 4 12s3.59 8 8 8h2.5c.28 0 .5-.22.5-.5v-.35c0-1.78 1.18-3.36 2.88-3.97 1.27-.46 2.12-1.68 2.12-3.18 0-4.41-3.59-8-8-8zm-3.5 9c-.83 0-1.5-.67-1.5-1.5S7.67 10 8.5 10s1.5.67 1.5 1.5S9.33 13 8.5 13zm3.5-4c-.83 0-1.5-.67-1.5-1.5S11.17 6 12 6s1.5.67 1.5 1.5S12.83 9 12 9zm4 1c-.83 0-1.5-.67-1.5-1.5S15.17 7 16 7s1.5.67 1.5 1.5S16.83 10 16 10z' />
                  </svg>
                </button>

                <div className='gp-palette'>
                  {GROUP_COLORS.map((c) => (
                    <button
                      key={c}
                      type='button'
                      className='gp-swatch'
                      data-color={c}
                      style={{ backgroundColor: SWATCH_HEX[c] }}
                      aria-label={c}
                      onPointerDown={stopAll}
                      onPointerUp={stopAll}
                      onPointerMove={stopAll}
                      onClick={(e) => {
                        e.stopPropagation();
                        applyColor(c);
                      }}
                    />
                  ))}
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className='relative min-w-0 max-w-[85%]'>
            <div
              ref={scrollContainerRef}
              className={clsx(
                'flex h-28 gap-2 overflow-x-auto overflow-y-hidden',
                'library-list-item',
              )}
              style={{
                scrollbarWidth: 'none',
                msOverflowStyle: 'none',
                WebkitOverflowScrolling: 'touch',
                transform: 'translateZ(0)',
                willChange: 'scroll-position',
              }}
              onScroll={handleScroll}
            >
              {group.books.map((book) => (
                <div
                  key={book.hash}
                  className='relative aspect-[28/41] h-full shrink-0'
                >
                  <BookCover
                    book={book}
                    coverFit={coverFit}
                    isPreview
                    showSpine={skeuomorphicCovers ?? settings.librarySkeuomorphicCovers}
                    imageClassName='rounded-[2px]'
                  />
                </div>
              ))}
            </div>
            {showLeftArrow && (
              <div className='absolute left-[-0.5px] top-0 h-full w-12'>
                <div className='from-base-200/85 via-base-200/20 absolute inset-0 bg-linear-to-r to-transparent'></div>
                <button
                  aria-label={_('Scroll left')}
                  onClick={handleLeftArrowClick}
                  onPointerDown={(e) => stopEvent(e)}
                  onPointerUp={(e) => stopEvent(e)}
                  onPointerMove={(e) => stopEvent(e)}
                  onPointerCancel={(e) => stopEvent(e)}
                  onPointerLeave={(e) => stopEvent(e)}
                  className='absolute left-2 top-1/2 -translate-y-1/2 transition-all duration-200 hover:scale-110'
                >
                  <div className='bg-base-100 border-base-content/10 hover:border-base-content/30 rounded-full border p-1 shadow-xs transition-colors duration-200'>
                    <MdChevronLeft
                      size={16}
                      className='text-base-content/50 hover:text-base-content/70'
                    />
                  </div>
                </button>
              </div>
            )}
            {showRightArrow && (
              <div className='absolute right-[-0.5px] top-0 h-full w-12'>
                <div className='from-base-200/85 via-base-200/20 absolute inset-0 bg-linear-to-l to-transparent'></div>
                <button
                  aria-label={_('Scroll right')}
                  onClick={handleRightArrowClick}
                  onPointerDown={(e) => stopEvent(e)}
                  onPointerUp={(e) => stopEvent(e)}
                  onPointerMove={(e) => stopEvent(e)}
                  onPointerCancel={(e) => stopEvent(e)}
                  onPointerLeave={(e) => stopEvent(e)}
                  className='absolute right-2 top-1/2 -translate-y-1/2 transition-all duration-200 hover:scale-110'
                >
                  <div className='bg-base-100 border-base-content/10 hover:border-base-content/30 rounded-full border p-1 shadow-xs transition-colors duration-200'>
                    <MdChevronRight
                      size={16}
                      className='text-base-content/50 hover:text-base-content/70'
                    />
                  </div>
                </button>
              </div>
            )}
          </div>
        )}
        {mode === 'list' && (
          <div
            title={groupLabel}
            className='text-base-content/75 w-28 min-w-24 max-w-40 overflow-hidden text-ellipsis text-base font-semibold'
          >
            {groupLabel}
          </div>
        )}
        {groupSelected && (
          <div className='absolute inset-0 bg-black opacity-30 transition-opacity duration-300'></div>
        )}
        {isSelectMode && (
          <div className='absolute bottom-1 right-1'>
            {groupSelected ? (
              <MdCheckCircle className='fill-blue-500' />
            ) : (
              <MdCheckCircleOutline className='fill-gray-300 drop-shadow-xs' />
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default GroupItem;
